-- A write that changes nothing, or only a deal's place in its kanban column, keeps the old date.
-- `crm.manual_dates` lets a data migration or a test set the date itself.
CREATE FUNCTION "crm"."touch_updated_at"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF current_setting('crm.manual_dates', true) = 'on' THEN
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW) - 'updated_at' - 'index') IS DISTINCT FROM (to_jsonb(OLD) - 'updated_at' - 'index') THEN
    NEW.updated_at = now();
  ELSE
    NEW.updated_at = OLD.updated_at;
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER "companies_touch_updated_at" BEFORE UPDATE ON "crm"."companies" FOR EACH ROW EXECUTE FUNCTION "crm"."touch_updated_at"();
--> statement-breakpoint
