CREATE FUNCTION "crm"."record_deal_stage"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.stage IS DISTINCT FROM OLD.stage THEN
    INSERT INTO "crm"."deal_stage_history" ("deal_id", "from_stage", "to_stage")
    VALUES (NEW.id, CASE WHEN TG_OP = 'UPDATE' THEN OLD.stage END, NEW.stage);
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER "deals_stage_history" AFTER INSERT OR UPDATE OF "stage" ON "crm"."deals" FOR EACH ROW EXECUTE FUNCTION "crm"."record_deal_stage"();
--> statement-breakpoint
