-- A new deal comes from where its first contact, or else its company, came from.
CREATE FUNCTION "crm"."inherit_deal_lead_source"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.lead_source IS NULL AND NEW.contact_ids IS NOT NULL THEN
    SELECT co.lead_source INTO NEW.lead_source FROM "crm"."contacts" co
    WHERE co.id = ANY(NEW.contact_ids) AND co.lead_source IS NOT NULL
    ORDER BY array_position(NEW.contact_ids, co.id) LIMIT 1;
  END IF;
  IF NEW.lead_source IS NULL AND NEW.company_id IS NOT NULL THEN
    SELECT c.lead_source INTO NEW.lead_source FROM "crm"."companies" c WHERE c.id = NEW.company_id;
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER "deals_inherit_lead_source" BEFORE INSERT ON "crm"."deals" FOR EACH ROW EXECUTE FUNCTION "crm"."inherit_deal_lead_source"();
--> statement-breakpoint
-- The summary views list the tables' columns as they were when made, so they are made again.
DROP VIEW "crm"."companies_summary";
--> statement-breakpoint
CREATE VIEW "crm"."companies_summary" AS
SELECT
    c.*,
    count(DISTINCT d.id)::int AS nb_deals,
    count(DISTINCT co.id)::int AS nb_contacts
FROM "crm"."companies" c
    LEFT JOIN "crm"."deals" d ON c.id = d.company_id
    LEFT JOIN "crm"."contacts" co ON c.id = co.company_id
GROUP BY c.id;
--> statement-breakpoint
DROP VIEW "crm"."contacts_summary";
--> statement-breakpoint
CREATE VIEW "crm"."contacts_summary" AS
SELECT
    co.*,
    (jsonb_path_query_array(co.email_jsonb, '$[*]."email"'))::text AS email_fts,
    (jsonb_path_query_array(co.phone_jsonb, '$[*]."number"'))::text AS phone_fts,
    c.name AS company_name,
    (count(DISTINCT t.id) FILTER (WHERE t.done_date IS NULL))::int AS nb_tasks
FROM "crm"."contacts" co
    LEFT JOIN "crm"."tasks" t ON co.id = t.contact_id
    LEFT JOIN "crm"."companies" c ON co.company_id = c.id
GROUP BY co.id, c.name;
